UPDATE companies SET description='McLean Furniture Gallery has operated in the Washington, D.C. metropolitan area since 1984, when Tehmina Khan and her husband Imran Khan founded the business in Tysons, Virginia. Khan’s design career began five decades earlier with a haute couture line carried by Saks Fifth Avenue and other department stores before she turned her focus to interiors.

Clientele ranges from individual homeowners furnishing new residences to high-profile buyers including heads of state, corporate executives, and government officials throughout the D.C. region and beyond. The gallery’s product mix spans traditional to contemporary styles across the residential furnishing segment.

Khan’s industry recognition — including furniture designs named in her honor by Harden and Henredon and a 2021 “Best Furniture Store” award from DC Modern Luxury Magazine — underscores the gallery’s positioning as an omni-channel resource that combines product breadth with collaborative design services.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Interior design services", "Custom window treatments", "Re-upholstery", "Furniture retail", "Lighting retail", "Accessories retail", "Rug retail"], "industries": ["Residential interior design", "Home furnishing", "Luxury furniture retail"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 1984 by Tehmina Khan and Imran Khan -> /about-us", "Family-owned (husband and wife founders) -> /about-us", "Headquarters in Tysons, Virginia (showroom at 8219 Leesburg Pike, 5th Floor) -> /", "Represents 40+ American furniture manufacturers -> /about-us, /services", "Offers furniture, lighting, accessories, rugs, custom window treatments -> /services", "Provides interior design services and re-upholstery -> /services", "Clientele includes heads of state, corporate executives, government officials -> /about-us", "Recognized as Best Furniture Store 2021 by DC Modern Luxury Magazine -> /about-us", "Harden and Henredon created furniture named in Tehmina Khan''s honor -> /about-us", "Tehmina Khan''s background in haute couture (Saks Fifth Avenue, etc.) -> /about-us"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "We proudly represent 40+ manufacturers including heritage American furniture houses", "founded_year": "1984", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='mclean-furniture-mfg-design-studio' AND approved AND profile IS NULL;
UPDATE companies SET description='Pioneer Meats operates from Big Timber, Montana, where Brian and Kary Engle established the business in 2006 on a 20-acre property. Brian’s path into meat processing began in his youth, cutting meat with his family, and later processing deer and elk for friends from a converted semi-trailer between 1993 and 1997. After earning an Animal Sciences degree from Montana State University, he and Kary restarted the venture, building a USDA-inspected facility at the current location.

The company provides custom meat processing for both domestic livestock and wild game, producing a range of cured and smoked products including snack sticks, bratwurst, bacon, sausage, hot dogs, along with proprietary sauces and spice blends. A retail store on-site sells these items directly to consumers. The facility handles cutting, grinding, curing, smoking, and packaging, though specific equipment and headcount are not disclosed.

Pioneer Meats serves individual hunters, livestock owners, and retail customers across Montana and beyond. The business is active in the meat processing industry through membership in the Montana Meat Processors Association, the North West Meat Processors Association, and the American Association of Meat Processors, with Brian Engle holding board positions in the first and third organizations.

The Engles attribute their reputation to a focus on award-winning quality; since 2005 the company has earned multiple Grand Champion titles at state and regional cured-meat shows, including Best of Show for bacon in 2009. Community involvement, from supporting local food banks to agricultural scholarships, is also cited as a core value.', certifications=ARRAY['USDA inspected']::text[], profile='{"capabilities": ["Custom meat processing", "Wild game processing", "Domestic meat processing", "Sausage manufacturing", "Bacon curing", "Snack stick production", "Bratwurst production", "Hot dog manufacturing", "Sauce production", "Spice blending", "Retail sales"], "industries": ["Meat processing", "Food manufacturing", "Agriculture", "Retail"], "materials": ["Beef", "Pork", "Wild game (deer, elk)", "Spices", "Sauces"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["USDA-inspected facility", "Multiple Grand Champion awards at state and regional competitions", "Custom processing for both domestic and wild game", "Family-owned with deep roots in Montana agriculture", "Active in industry associations (MMPA, NWPA, AAMP)"], "facts_used": ["Founded 2006 -> db", "Headquarters Big Timber, Montana -> db", "Founders Brian and Kary Engle -> /about-us", "Brian Engle started cutting meat young, ran business 1993-1997 -> /about-us", "USDA-inspected facility on 20 acres -> /about-us", "Custom processing for domestic and wild game -> /", "Products: snack sticks, bratwurst, bacon, sausage, hot dogs, sauces, spices -> /", "Retail store on-site -> /", "Member of Montana Meat Processors Association, North West Meat Processors Association, American Association of Meat Processors -> /about-us", "Brian Engle on Board of Directors for MMPA and AAMP -> /about-us", "Multiple Grand Champion awards 2009-2014, Best of Show bacon 2009 -> /about-us", "Community support: food banks, scholarships, youth sports -> /about-us"], "company_type": "Manufacturer", "makes_products":